import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice, invoiceTotals, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement returns empty list for customer with no invoices', () => {
  const result = statement('C-001', [], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement rejects unknown customer', () => {
  const result = statement('C-999', [], '2026-10-07');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement includes issued invoices issued on or before asOf', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
});

test('statement excludes invoices issued after asOf', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-01');
});

test('statement excludes draft invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv1, []).value;

  const result = statement('C-001', [inv2, issued], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued.number);
});

test('statement includes partially_paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 5000, date: '2026-10-05' }).value;

  const result = statement('C-001', [paid], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].due, 21400); // Some amount still owed
});

test('statement excludes paid invoices', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const totals = invoiceTotals(issued);
  const paid = recordPayment(issued, { amount: totals.total, date: '2026-10-05' }).value;

  const result = statement('C-001', [paid], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement sorts invoices by issueDate ascending', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;
  const issued3 = issueInvoice(inv3, ['INV-2026-0001', 'INV-2026-0002']).value;

  const result = statement('C-001', [issued1, issued2, issued3], '2026-10-15');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-01');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-05');
  assert.equal(result.value.invoices[2].issueDate, '2026-10-10');
});

test('statement calculates correct totalDue', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2026-10-07');
  assert.equal(result.ok, true);
  const total1 = invoiceTotals(issued1).total;
  const total2 = invoiceTotals(issued2).total;
  assert.equal(result.value.totalDue, total1 + total2);
});

test('statement includes invoice number, issueDate, dueDate, total, and due', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET30',
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = statement('C-001', [issued], '2026-10-07');
  assert.equal(result.ok, true);
  const inv_stmt = result.value.invoices[0];
  assert.equal(inv_stmt.number, issued.number);
  assert.equal(inv_stmt.issueDate, '2026-10-01');
  assert.equal(inv_stmt.dueDate, '2026-10-31');
  assert.ok(Number.isInteger(inv_stmt.total));
  assert.ok(Number.isInteger(inv_stmt.due));
  assert.equal(inv_stmt.due, inv_stmt.total);
});

test('statement only includes invoices for specified customer', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued1 = issueInvoice(inv1, []).value;
  const issued2 = issueInvoice(inv2, ['INV-2026-0001']).value;

  const result = statement('C-001', [issued1, issued2], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, issued1.number);
});

test('statement normalizes customer ID', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = statement('c-001', [issued], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
});

test('statement normalizes customer ID with spaces', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = statement(' c-001 ', [issued], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
});

test('statement with partially paid invoice shows correct due', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const issued = issueInvoice(inv, []).value;
  const paid = recordPayment(issued, { amount: 30000, date: '2026-10-05' }).value;

  const result = statement('C-001', [paid], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  const totals = invoiceTotals(paid);
  assert.equal(result.value.invoices[0].due, totals.total - 30000);
  assert.equal(result.value.totalDue, totals.total - 30000);
});

test('statement with voucher includes voucher in total', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const withVoucher = applyVoucher(inv, { code: 'SAVE10', amount: 5000 }).value;
  const issued = issueInvoice(withVoucher, []).value;

  const result = statement('C-001', [issued], '2026-10-07');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  const totals = invoiceTotals(issued);
  assert.equal(result.value.invoices[0].total, totals.total);
});

test('statement on asOf date includes invoices issued that day', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  }).value;

  const issued = issueInvoice(inv, []).value;

  const result = statement('C-001', [issued], '2026-10-07');
